def choose_move(observation):
    # Defensive defaults
    x = observation.get("position", {}).get("x", 0)
    y = observation.get("position", {}).get("y", 0)

    # Try to infer a simple, robust heuristic that works across modes
    # 1) Prefer staying put if no clear objective
    # 2) If there are visible resources, move toward the closest
    # 3) If pursuing an evader, move toward their last known position
    # 4) If territory control, drift toward the center of owned cells if available

    # Common heuristics from observation fields
    resources = observation.get("resources", [])
    evader = observation.get("evader", {})
    owned = observation.get("owned_cells", [])

    # Initialize target delta to 0
    dx = 0
    dy = 0

    # Helper: distance in grid
    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    # 1) Resource collection: move toward closest resource if present
    if isinstance(resources, list) and resources:
        closest = None
        closest_d = None
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            d = dist((x, y), (rx, ry))
            if closest_d is None or d < closest_d:
                closest = (rx, ry)
                closest_d = d
        if closest is not None:
            if closest[0] > x:
                dx = 1
            elif closest[0] < x:
                dx = -1
            if closest[1] > y:
                dy = 1
            elif closest[1] < y:
                dy = -1
            return [dx, dy]

    # 2) Pursuit-evasion: chase last known evader position
    if isinstance(evader, dict) and evader:
        ex = evader.get("x", None)
        ey = evader.get("y", None)
        if ex is not None and ey is not None:
            if ex > x:
                dx = 1
            elif ex < x:
                dx = -1
            if ey > y:
                dy = 1
            elif ey < y:
                dy = -1
            return [dx, dy]

    # 3) Territory control: move toward near center of owned area if possible
    if isinstance(owned, list) and owned:
        # Compute simple centroid of owned cells
        sx = sum(c.get("x", 0) for c in owned) / len(owned)
        sy = sum(c.get("y", 0) for c in owned) / len(owned)
        if sx > x:
            dx = 1
        elif sx < x:
            dx = -1
        if sy > y:
            dy = 1
        elif sy < y:
            dy = -1
        if dx != 0 or dy != 0:
            return [dx, dy]

    # Default: small random-like movement but deterministic: try to move toward origin (0,0)
    if x > 0:
        dx = -1
    elif x < 0:
        dx = 1
    else:
        dx = 0

    if y > 0:
        dy = -1
    elif y < 0:
        dy = 1
    else:
        dy = 0

    return [dx, dy]

